  "tools": [
    {
      "type": "function",
      "name": "search_flights",
      "description": "Search for available flights. Returns a list of matching flights with pricing for all cabin classes. Each flight includes a cabin_prices map (e.g. {economy: 350, business: 875}). Use optional filters to narrow results by airline, time, stops, or max price.",
      "parameters": {
        "type": "object",
        "properties": {
          "origin": {
            "type": "string",
            "description": "Origin airport IATA code (e.g. 'ORD')"
          },
          "destination": {
            "type": "string",
            "description": "Destination airport IATA code (e.g. 'SFO')"
          },
          "date": {
            "type": "string",
            "description": "Departure date in YYYY-MM-DD format"
          },
          "airline": {
            "type": "string",
            "description": "Filter by airline IATA code (e.g. 'DL', 'UA')"
          },
          "time_range": {
            "type": "string",
            "enum": [
              "early_morning",
              "morning",
              "afternoon",
              "evening",
              "red_eye"
            ],
            "description": "Filter by departure time window: early_morning (5am-8am), morning (8am-12pm), afternoon (12pm-5pm), evening (5pm-9pm), red_eye (9pm-5am)"
          },
          "max_stops": {
            "type": "integer",
            "description": "Maximum number of stops (0 = nonstop only)"
          },
          "max_price": {
            "type": "integer",
            "description": "Maximum price in USD (filters on cheapest cabin). Use -1 for no price limit."
          }
        },
        "required": [
          "origin",
          "destination",
          "date"
        ]
      }
    },
    {
      "type": "function",
      "name": "get_user_details",
      "description": "Look up a customer's account details including name, email, loyalty tier, and points balance.",
      "parameters": {
        "type": "object",
        "properties": {
          "user_id": {
            "type": "string",
            "description": "Customer user ID (e.g. 'user_001')"
          }
        },
        "required": [
          "user_id"
        ]
      }
    },
    {
      "type": "function",
      "name": "get_user_reservations",
      "description": "List all reservation IDs for a customer's flight bookings, hotel reservations, and car rentals. Use get_booking, get_hotel_reservation, or get_car_rental to look up details by ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "user_id": {
            "type": "string",
            "description": "Customer user ID (e.g. 'user_001')"
          }
        },
        "required": [
          "user_id"
        ]
      }
    },
    {
      "type": "function",
      "name": "get_booking",
      "description": "Retrieve the details of an existing booking by its booking ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "booking_id": {
            "type": "string",
            "description": "The booking ID (e.g. 'BK-0001')"
          }
        },
        "required": [
          "booking_id"
        ]
      }
    },
    {
      "type": "function",
      "name": "get_policies",
      "description": "Look up travel policies for a specific topic. Topics: 'cancel' (flight cancellation rules), 'change' (flight change rules), 'baggage' (baggage allowance by fare class and loyalty tier), 'delay_compensation' (delay/cancellation compensation), 'loyalty' (loyalty points redemption rates and rules), 'upgrade' (cabin class upgrade eligibility and pricing), 'hotel_cancel' (hotel reservation cancellation rules), 'car_rental_cancel' (car rental cancellation rules).",
      "parameters": {
        "type": "object",
        "properties": {
          "topic": {
            "type": "string",
            "enum": [
              "cancel",
              "change",
              "baggage",
              "delay_compensation",
              "loyalty",
              "upgrade",
              "hotel_cancel",
              "car_rental_cancel"
            ],
            "description": "The policy topic to look up"
          },
          "cabin_class": {
            "type": "string",
            "enum": [
              "basic_economy",
              "economy",
              "business",
              "first"
            ],
            "description": "The cabin class (affects cancellation/change/baggage/upgrade rules)"
          },
          "loyalty_tier": {
            "type": "string",
            "enum": [
              "basic",
              "silver",
              "gold",
              "platinum"
            ],
            "description": "Customer loyalty tier (affects baggage allowance and points redemption rate)"
          },
          "route_type": {
            "type": "string",
            "enum": [
              "domestic",
              "international"
            ],
            "description": "Route type (affects cancellation/change fees and free window duration)"
          }
        },
        "required": [
          "topic"
        ]
      }
    },
    {
      "type": "function",
      "name": "create_booking",
      "description": "Book a flight for a customer. Requires flight_id, user_id, cabin_class, seat_type, meal_preference, add_wifi, add_extra_legroom, add_insurance, and payment_method. cabin_class selects the fare tier from the flight's cabin_prices. seat_type must be one of: window, middle, aisle. payment_method must be one of: credit_card, points, points_plus_cash. For points or points_plus_cash payment, the system will check the customer's loyalty balance. Persisted booking preferences must be passed explicitly; they are not inferred from the user profile.",
      "parameters": {
        "type": "object",
        "properties": {
          "flight_id": {
            "type": "string",
            "description": "Flight ID from search results"
          },
          "user_id": {
            "type": "string",
            "description": "Customer user ID"
          },
          "cabin_class": {
            "type": "string",
            "enum": [
              "basic_economy",
              "economy",
              "business",
              "first"
            ],
            "description": "Cabin class to book (must be available in the flight's cabin_prices)"
          },
          "seat_type": {
            "type": "string",
            "enum": [
              "window",
              "middle",
              "aisle"
            ],
            "description": "Seat preference (required)"
          },
          "payment_method": {
            "type": "string",
            "enum": [
              "credit_card",
              "points",
              "points_plus_cash"
            ],
            "description": "Payment method (required). 'points' uses loyalty points for full payment. 'points_plus_cash' uses points + cash — requires cash_amount parameter."
          },
          "cash_amount": {
            "type": "integer",
            "description": "Cash amount in USD to charge when payment_method is 'points_plus_cash'. Required for points_plus_cash payments."
          },
          "points_used": {
            "type": "integer",
            "description": "Number of loyalty points to redeem. Required when payment_method is 'points' or 'points_plus_cash'."
          },
          "meal_preference": {
            "type": "string",
            "enum": [
              "standard",
              "vegetarian",
              "vegan",
              "kosher",
              "halal",
              "gluten_free"
            ],
            "description": "Meal preference"
          },
          "add_wifi": {
            "type": "boolean",
            "description": "Add in-flight WiFi"
          },
          "add_extra_legroom": {
            "type": "boolean",
            "description": "Request extra legroom seat"
          },
          "add_insurance": {
            "type": "boolean",
            "description": "Add travel insurance"
          },
          "paid_checked_bags": {
            "type": "integer",
            "description": "Number of extra checked bags beyond free allowance ($35 each)"
          }
        },
        "required": [
          "flight_id",
          "user_id",
          "cabin_class",
          "seat_type",
          "meal_preference",
          "add_wifi",
          "add_extra_legroom",
          "add_insurance",
          "payment_method"
        ]
      }
    },
    {
      "type": "function",
      "name": "search_hotels",
      "description": "Search for available hotels in a city. Filter by dates, room type, and price.",
      "parameters": {
        "type": "object",
        "properties": {
          "city": {
            "type": "string",
            "description": "City name or airport code area (e.g. 'LHR', 'CDG', 'MIA')"
          },
          "check_in": {
            "type": "string",
            "description": "Check-in date in YYYY-MM-DD format"
          },
          "check_out": {
            "type": "string",
            "description": "Check-out date in YYYY-MM-DD format"
          },
          "room_type": {
            "type": "string",
            "enum": [
              "standard",
              "suite"
            ],
            "description": "Filter by room type"
          },
          "max_price": {
            "type": "integer",
            "description": "Maximum nightly rate in USD. Use -1 for no limit."
          }
        },
        "required": [
          "city"
        ]
      }
    },
    {
      "type": "function",
      "name": "book_hotel",
      "description": "Book a hotel option returned by search_hotels for a customer.",
      "parameters": {
        "type": "object",
        "properties": {
          "hotel_id": {
            "type": "string",
            "description": "Hotel option ID from search_hotels"
          },
          "user_id": {
            "type": "string",
            "description": "Customer user ID"
          }
        },
        "required": [
          "hotel_id",
          "user_id"
        ]
      }
    },
    {
      "type": "function",
      "name": "get_hotel_reservation",
      "description": "Retrieve the details of an existing hotel reservation by its reservation ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "reservation_id": {
            "type": "string",
            "description": "The hotel reservation ID (e.g. 'HR-0001')"
          }
        },
        "required": [
          "reservation_id"
        ]
      }
    },
    {
      "type": "function",
      "name": "search_car_rentals",
      "description": "Search for available car rentals at a location. Filter by dates, car class, and daily rate.",
      "parameters": {
        "type": "object",
        "properties": {
          "pickup_location": {
            "type": "string",
            "description": "Pickup location airport code (e.g. 'LHR', 'MIA')"
          },
          "pickup_date": {
            "type": "string",
            "description": "Pickup date in YYYY-MM-DD format"
          },
          "dropoff_date": {
            "type": "string",
            "description": "Dropoff date in YYYY-MM-DD format"
          },
          "car_class": {
            "type": "string",
            "enum": [
              "economy",
              "midsize",
              "suv",
              "luxury"
            ],
            "description": "Filter by car class"
          },
          "max_daily_rate": {
            "type": "integer",
            "description": "Maximum daily rate in USD. Use -1 for no limit."
          }
        },
        "required": [
          "pickup_location"
        ]
      }
    },
    {
      "type": "function",
      "name": "get_car_rental",
      "description": "Retrieve the details of an existing car rental by its rental ID.",
      "parameters": {
        "type": "object",
        "properties": {
          "rental_id": {
            "type": "string",
            "description": "The car rental ID (e.g. 'CR-0001')"
          }
        },
        "required": [
          "rental_id"
        ]
      }
    }
  ]
}
